    90→    setTimeout(check, 1500);
    91→    setTimeout(check, 3000);
    92→  })();
    93→  </script>
    94→{% else %}
    95→
    96→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
    97→
    98→<div
    99→  id="zcc-widget-{{ block.id }}"
   100→  data-zcc-widget="true"
   101→  data-shop="{{ shop.permanent_domain }}"
   102→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
   103→  data-block="{{ block.id }}"
   104→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
   105→  {{ block.shopify_attributes }}
   106→></div>
   107→
   108→<script>
   109→(function () {
   110→  // Wait for app embed to set window.__zccAppEnabled.
   111→  // App embed (target: body) may load after this section block, so we poll briefly.
   112→  var maxWait = 3000; // ms
   113→  var interval = 50;  // ms
   114→  var elapsed = 0;
   115→
   116→  function tryInit() {
   117→    if (window.__zccAppEnabled) {
   118→      init();
   119→    } else if (elapsed < maxWait) {
   120→      elapsed += interval;
   121→      setTimeout(tryInit, interval);
   122→    }
   123→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
   124→  }
   125→
   126→  // Start checking — if already set, runs immediately
   127→  if (document.readyState === 'loading') {
   128→    document.addEventListener('DOMContentLoaded', tryInit);
   129→  } else {
   130→    tryInit();
   131→  }
   132→
   133→  function init() {
   134→  var ROOT_ID = "zcc-widget-{{ block.id }}";
   135→  var container = document.getElementById(ROOT_ID);
   136→  if (!container) return;
   137→
   138→  var SHOP = container.dataset.shop;
   139→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
   140→
   141→  // Try embedded config from metafield first (instant, no network needed)
   142→  var configStr = container.getAttribute("data-config");
   143→  if (configStr) {
   144→    try {
   145→      renderWidget(JSON.parse(configStr));
   146→      return;
   147→    } catch (e) {
   148→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
   149→    }
   150→  }
   151→
   152→  // Fallback: fetch config from API
   153→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
   154→    .then(function (r) {
   155→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
   156→      return r.json();
   157→    })
   158→    .then(function (cfg) { renderWidget(cfg); })
   159→    .catch(function (err) {
   160→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
   161→      renderWidget({});
   162→    });
   163→
   164→  function renderWidget(cfg) {
   165→    // Merge with defaults
